public class Marks {
    static int total(int[] marks) {
        int sum = 0;                              // running total.
        for (int i = 0; i < marks.length; i++) {  // 0 .. length - 1.
            sum += marks[i];
        }
        return sum;                               // empty array: 0.
    }

    static void doubleAll(int[] marks) {
        for (int i = 0; i < marks.length; i++) marks[i] *= 2;   // index: modifies.
    }

    static int countUntilSentinel(int[] data) {   // stop at -1 or the end.
        int i = 0;
        while (i < data.length && data[i] != -1) i++;           // progress each pass.
        return i;
    }

    public static void main(String[] args) {
        int[] marks = {7, 9, 8};
        for (int m : marks) System.out.print(m + " ");        // read-only visit.
        System.out.println("total " + total(marks));           // 24
        doubleAll(marks);                                       // {14, 18, 16}
        System.out.println(countUntilSentinel(new int[]{4, 2, -1, 5}));   // 2
    }
}
